# frozen_string_literal: true

module Hookd
  # Owner secret handling for servers with owner secrets enabled, where each
  # hook is readable only with the secret it was registered under.
  module OwnerSecret
    # Header carrying the owner secret.
    SECRET_HEADER = 'X-Hookd-Secret'

    # The owner secret in use, possibly generated by the server on the first
    # registration. Store it to read the hooks later.
    # @return [String, nil]
    def secret
      @secret_lock.synchronize { @secret }
    end

    # Set the owner secret; nil lets the next registration adopt a new one.
    # @param value [String, nil]
    def secret=(value)
      value = nil if value == ''
      @secret_lock.synchronize do
        @secret = value
        @settled = !value.nil?
      end
    end

    private

    def init_secret(value)
      @secret_lock = Mutex.new
      @register_lock = Mutex.new
      self.secret = value
    end

    # Registers and returns the response with the secret its hooks belong to:
    # the one sent, or the one the server generated, adopted when the client
    # has none. Until a secret is known, registrations run one at a time, so
    # concurrent first calls end up under the same owner.
    def post_register(body)
      return register_as(body) if @secret_lock.synchronize { @settled }

      @register_lock.synchronize { register_as(body) }
    end

    def register_as(body)
      sent = secret
      response = post('/register', body, as: sent)
      owner = (response['secret'] if response.is_a?(Hash)) || sent
      @secret_lock.synchronize do
        @secret ||= owner
        @settled = true
      end
      [response, owner]
    end

    def secret_headers(value = secret)
      value ? { SECRET_HEADER => value } : {}
    end
  end
end
